window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8c9faf4dc05b7ef6"]={"versions": [{"id": "FIG-8c9faf4dc05b7ef6", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines atomaren Teilschritts der E2E-Profil-4m-Prüfroutine (<code>E2E_P04mCheck</code>) im AUTOSAR-E2E-Protokoll (PRS E2E Protocol). Es beschreibt das Auslesen und Deserialisieren der 32-Bit-DataID aus dem serialisierten Datenstrom.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Kontext / Aktivitätsbereich</strong>: Aufrufkontext <code>E2E_P04mCheck()</code>.\n</li><li><strong>Eingangsdaten</strong>: Byte-Array <code>Data[]</code> mit Byte-Offset <code>Offset</code> (Bereich <code>Offset+4</code> bis <code>Offset+7</code>).\n</li><li><strong>Lokale Variable / Ziel</strong>: <code>uint32 ReceivedDataID</code> (32-Bit vorzeichenlose Ganzzahl).\n</li><li><strong>Format / Konvertierungsvorschrift</strong>: Big-Endian-Byte-Reihenfolge.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Startknoten</strong>: Beginn des Ausleseschritts für die DataID.\n</li><li><strong>Aktionsknoten</strong>: Kopieren der vier Bytes <code>Data[Offset+4...Offset+7]</code> in Big-Endian-Reihenfolge in die lokale Variable <code>ReceivedDataID</code>.\n</li><li><strong>Endknoten</strong>: Abschluss der Aktivität und Übergang zum nachfolgenden Prüfschritt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Anforderung gemäß <code>[PRS_E2E_00776]</code> für Client- und Serverseite in <code>E2E_P04mCheck()</code>. Für Implementierer ist sicherzustellen, dass die DataID über 4 Bytes ab dem definierten Offset (<code>Offset+4</code> bis <code>Offset+7</code>) strikt im Big-Endian-Format extrahiert wird, bevor nachfolgende Plausibilitätsprüfungen gegen die konfigurierte DataID stattfinden.</p>"}, {"id": "FIG-7223936e332c7f24", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines atomaren Teilschritts der E2E-Profil-4m-Prüfroutine (<code>E2E_P04mCheck</code>) im AUTOSAR-E2E-Protokoll (PRS E2E Protocol). Es beschreibt das Auslesen und Deserialisieren der 32-Bit-DataID aus dem serialisierten Datenstrom.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Kontext / Aktivitätsbereich</strong>: Aufrufkontext <code>E2E_P04mCheck()</code>.\n</li><li><strong>Eingangsdaten</strong>: Byte-Array <code>Data[]</code> mit Byte-Offset <code>Offset</code> (Bereich <code>Offset+4</code> bis <code>Offset+7</code>).\n</li><li><strong>Lokale Variable / Ziel</strong>: <code>uint32 ReceivedDataID</code> (32-Bit vorzeichenlose Ganzzahl).\n</li><li><strong>Format / Konvertierungsvorschrift</strong>: Big-Endian-Byte-Reihenfolge.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Startknoten</strong>: Beginn des Ausleseschritts für die DataID.\n</li><li><strong>Aktionsknoten</strong>: Kopieren der vier Bytes <code>Data[Offset+4...Offset+7]</code> in Big-Endian-Reihenfolge in die lokale Variable <code>ReceivedDataID</code>.\n</li><li><strong>Endknoten</strong>: Abschluss der Aktivität und Übergang zum nachfolgenden Prüfschritt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Anforderung gemäß <code>[PRS_E2E_00776]</code> für Client- und Serverseite in <code>E2E_P04mCheck()</code>. Für Implementierer ist sicherzustellen, dass die DataID über 4 Bytes ab dem definierten Offset (<code>Offset+4</code> bis <code>Offset+7</code>) strikt im Big-Endian-Format extrahiert wird, bevor nachfolgende Plausibilitätsprüfungen gegen die konfigurierte DataID stattfinden.</p>"}], "trans": [{"from": "FIG-8c9faf4dc05b7ef6", "to": "FIG-7223936e332c7f24", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
